  </svg>`,
};

/* ── Validation rules ── */
const validators = {
  fullName(value) {
    if (!value.trim()) return 'Full name is required.';
    if (value.trim().length < 2) return 'Full name must be at least 2 characters.';
    return null;
  },
  email(value) {
    if (!value.trim()) return 'Email address is required.';
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())) return 'Enter a valid email address (e.g. you@example.com).';
    return null;
  },
  phone(value) {
    if (!value.trim()) return null; // optional
    if (!/^(\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}$/.test(value.trim())) {
      return 'Enter a valid phone number matching the format shown below.';
    }
    return null;
  },
};

/* ── FormField component ── */
function FormField({ id, label, type = 'text', required = false, placeholder = '', helperText = '', autocomplete = '' }) {
  const errorId = `${id}-error`;
  const helperId = helperText ? `${id}-helper` : null;
  const describedBy = [helperId, errorId].filter(Boolean).join(' ');

  return `
    <div class="form-field" id="${id}-field">
      <label for="${id}">
        ${label}
        ${required ? `<span class="required-mark" aria-hidden="true">*</span>` : '<span class="optional-tag" style="font-weight:400;font-size:0.78rem;color:var(--color-text-muted);margin-left:0.2rem;">(optional)</span>'}
      </label>
      <input
        type="${type}"
        id="${id}"
        name="${id}"
        ${required ? 'required aria-required="true"' : ''}
        ${autocomplete ? `autocomplete="${autocomplete}"` : ''}
        placeholder="${placeholder}"
        aria-describedby="${describedBy}"
      />
      ${helperText ? `
      <p class="helper-text" id="${helperId}">
        ${Icons.info}
        <span>${helperText}</span>
      </p>` : ''}
      <p class="error-message" id="${errorId}" role="alert" aria-live="polite"></p>
    </div>`;
}

/* ── ContactForm component ── */
function ContactForm() {
  return `
    <form id="contact-form" novalidate aria-label="Contact support form">
      <div id="form-status" class="form-status" role="status" aria-live="polite" aria-atomic="true"></div>

      ${FormField({
        id: 'fullName',
        label: 'Full Name',
        type: 'text',
        required: true,
        placeholder: 'Jane Smith',
        autocomplete: 'name',
      })}

      ${FormField({
        id: 'email',
        label: 'Email Address',
        type: 'email',
        required: true,
        placeholder: 'you@example.com',
        autocomplete: 'email',
      })}

      ${FormField({
        id: 'phone',
        label: 'Phone Number',
        type: 'tel',
        required: false,
        placeholder: '(555) 867-5309',
        autocomplete: 'tel',
        helperText: 'Accepted formats: (555) 867-5309 &nbsp;·&nbsp; 555-867-5309 &nbsp;·&nbsp; +1 555 867 5309',
      })}

      <button type="submit" class="btn-submit">Send Message</button>
    </form>`;
}

/* ── Page component ── */
function Page() {
  return `
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header>
      <div class="badge">Support</div>
      <h1>Get in Touch</h1>
      <p>Fill out the form below and our team will respond within 24 hours.</p>
    </header>

    <main id="main-content" tabindex="-1">
      <div class="card">
        ${ContactForm()}
      </div>
    </main>

    <footer>
      <p>Fields marked <span aria-label="required">*</span> are required.</p>
    </footer>`;
}

/* ── Mount & wire up validation ── */
function mount() {
  document.getElementById('app').innerHTML = Page();

  const form = document.getElementById('contact-form');
  const statusEl = document.getElementById('form-status');

  const fields = [
    { id: 'fullName', validate: validators.fullName },
    { id: 'email',    validate: validators.email },
    { id: 'phone',    validate: validators.phone },
  ];

  /* Show / clear a single field's error */
  function setFieldError(id, message) {
    const input   = document.getElementById(id);
    const errorEl = document.getElementById(`${id}-error`);
    if (!input || !errorEl) return;

    if (message) {
      input.setAttribute('aria-invalid', 'true');
      errorEl.innerHTML = `${Icons.error}<span>${message}</span>`;
      errorEl.classList.add('visible');
    } else {
      input.removeAttribute('aria-invalid');
      errorEl.textContent = '';
      errorEl.classList.remove('visible');
    }
  }

  /* Validate a single field on blur */
  fields.forEach(({ id, validate }) => {
    const input = document.getElementById(id);
    if (!input) return;

    input.addEventListener('blur', () => {
      const err = validate(input.value);
      setFieldError(id, err);
    });

    /* Clear error as user starts correcting */
    input.addEventListener('input', () => {
      if (input.getAttribute('aria-invalid') === 'true') {
        const err = validate(input.value);
        setFieldError(id, err);
      }
    });
  });

  /* Submit */
  form.addEventListener('submit', (e) => {
    e.preventDefault();

    statusEl.className = 'form-status';
    statusEl.textContent = '';

    let firstInvalid = null;
    let hasErrors = false;

    fields.forEach(({ id, validate }) => {
      const input = document.getElementById(id);
      const err = validate(input.value);
      setFieldError(id, err);
      if (err && !firstInvalid) firstInvalid = input;
      if (err) hasErrors = true;
    });

    if (hasErrors) {
      firstInvalid.focus();
      statusEl.innerHTML = `${Icons.error}<span>Please fix the errors above before submitting.</span>`;
      statusEl.classList.add('error-summary');
      return;
    }

    /* Simulate success */
    const btn = form.querySelector('.btn-submit');
    btn.disabled = true;
    btn.textContent = 'Sending…';

    setTimeout(() => {
      form.reset();
      fields.forEach(({ id }) => setFieldError(id, null));

      btn.disabled = false;
      btn.textContent = 'Send Message';

      statusEl.innerHTML = `${Icons.success}<span>Message sent! We'll be in touch within 24 hours.</span>`;
      statusEl.classList.add('success');
      statusEl.focus();
    }, 800);
  });
}

