        label: 'Full Name',
        type: 'text',
        required: true,
        placeholder: 'Jane Smith',
        autocomplete: 'name',
      })}

      ${FormField({
        id: 'email',
        label: 'Email Address',
        type: 'email',
        required: true,
        placeholder: 'you@example.com',
        autocomplete: 'email',
      })}

      ${FormField({
        id: 'phone',
        label: 'Phone Number',
        type: 'tel',
        required: false,
        placeholder: '(555) 867-5309',
        autocomplete: 'tel',
        helperText: 'Accepted formats: (555) 867-5309 &nbsp;·&nbsp; 555-867-5309 &nbsp;·&nbsp; +1 555 867 5309',
      })}

      <button type="submit" class="btn-submit">Send Message</button>
    </form>`;
}

/* ── Page component ── */
function Page() {
  return `
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header>
      <div class="badge">Support</div>
      <h1>Get in Touch</h1>
      <p>Fill out the form below and our team will respond within 24 hours.</p>
    </header>

