      return 'Enter a valid phone number matching the format shown below.';
    }
    return null;
  },
};

/* ── FormField component ── */
function FormField({ id, label, type = 'text', required = false, placeholder = '', helperText = '', autocomplete = '' }) {
  const errorId = `${id}-error`;
  const helperId = helperText ? `${id}-helper` : null;
  const describedBy = [helperId, errorId].filter(Boolean).join(' ');

  return `
    <div class="form-field" id="${id}-field">
      <label for="${id}">
        ${label}
        ${required ? `<span class="required-mark" aria-hidden="true">*</span>` : '<span class="optional-tag" style="font-weight:400;font-size:0.78rem;color:var(--color-text-muted);margin-left:0.2rem;">(optional)</span>'}
