        label: 'Full Name',
        type: 'text',
        required: true,
        placeholder: 'Jane Smith',
        autocomplete: 'name',
      })}

      ${FormField({
        id: 'email',
        label: 'Email Address',
        type: 'email',
        required: true,
        placeholder: 'you@example.com',
        autocomplete: 'email',
      })}

      ${FormField({
        id: 'phone',
        label: 'Phone Number',
        type: 'tel',
        required: false,
        placeholder: '(555) 867-5309',
        autocomplete: 'tel',
        helperText: 'Accepted formats: (555) 867-5309 &nbsp;·&nbsp; 555-867-5309 &nbsp;·&nbsp; +1 555 867 5309',
