cd /workspace/sandbox/variants/accessible_basic/simple-contact-form--framework-react--style-dark--validation-message-present/claude-sonnet-4.6__s3 && node -e "
const fs = require('fs');
const html = fs.readFileSync('index.html','utf8');
const css  = fs.readFileSync('styles.css','utf8');
const js   = fs.readFileSync('app.js','utf8');

// Basic sanity checks
const checks = [
  ['Has DOCTYPE',           /<!DOCTYPE html>/i.test(html)],
  ['Has lang=en',           /lang=\"en\"/.test(html)],
  ['Has title',             /<title>/.test(html)],
  ['Links styles.css',      /styles\.css/.test(html)],
  ['Links app.js',          /app\.js/.test(html)],
  ['form-field class',      /form-field/.test(js)],
  ['Required fullName',     /required.*aria-required/.test(js)],
  ['Required email',        /required.*aria-required/.test(js)],
  ['Phone optional',        /optional/.test(js)],
  ['Phone helper text',     /555/.test(js)],
  ['aria-invalid',          /aria-invalid/.test(js)],
  ['aria-describedby',      /aria-describedby/.test(js)],
  ['aria-live polite',      /aria-live.*polite/.test(js)],
  ['role=alert on errors',  /role=\"alert\"/.test(js)],
  ['Skip link',             /skip-link/.test(js)],
  ['focus first invalid',   /firstInvalid\.focus/.test(js)],
  ['Submit button',         /btn-submit/.test(js)],
  ['Dark bg var',           /--color-bg/.test(css)],
  ['Focus outline in FC',   /forced-colors/.test(css)],
];

let pass = 0, fail = 0;
checks.forEach(([name, ok]) => {
  console.log((ok ? '✓' : '✗') + ' ' + name);
  ok ? pass++ : fail++;
});
console.log(\`\nPassed \${pass}/\${checks.length}\`);
"

